import{_ as i,o as n,c as a,a0 as o}from"./chunks/framework.BXmxXpv-.js";const g=JSON.parse('{"title":"Research Directions","description":"Reducing the total cost of useful information acquisition through low-cost sensing, micro-computing, micro-communication, and device–edge–cloud collaboration.","frontmatter":{"title":"Research Directions","description":"Reducing the total cost of useful information acquisition through low-cost sensing, micro-computing, micro-communication, and device–edge–cloud collaboration."},"headers":[],"relativePath":"research.md","filePath":"en/research.md","lastUpdated":1793673474000}'),t={name:"research.md"};function r(s,e,l,c,d,m){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="research-directions" tabindex="-1">Research Directions <a class="header-anchor" href="#research-directions" aria-label="Permalink to &quot;Research Directions&quot;">​</a></h1><h2 id="research-goal" tabindex="-1">Research Goal <a class="header-anchor" href="#research-goal" aria-label="Permalink to &quot;Research Goal&quot;">​</a></h2><p>Intelligent systems need broad, continuous, and reliable information to understand and act in the physical world. Our long-term goal is to build large-scale sensing networks across places where people live and work and the natural environments connected to them. By enabling sustained observation in more locations, we seek to provide an information foundation for digital twins of the world, networked spatial intelligence, and embodied intelligence.</p><p>Reaching this goal requires sensing devices that can be deployed widely and operated over long periods. We study how to reduce the total cost of acquiring useful information while meeting information-quality, timeliness, and task requirements. This includes hardware, computing, communication, energy supply, and maintenance. Ultimately, we ask whether a system can affordably acquire richer information from more places for longer periods.</p><h2 id="device–edge–cloud-collaboration" tabindex="-1">Device–Edge–Cloud Collaboration <a class="header-anchor" href="#device–edge–cloud-collaboration" aria-label="Permalink to &quot;Device–Edge–Cloud Collaboration&quot;">​</a></h2><ul><li><strong>Devices</strong> interact with the physical world, convert physical quantities into digital information, and perform necessary front-end processing.</li><li><strong>Edge systems</strong> aggregate information within a region and provide initial computation, coordination, and timely feedback within their resource budgets.</li><li><strong>The cloud</strong> integrates information across regions, modalities, and time to support global modeling, analysis, prediction, and simulation.</li></ul><p>Together, these layers acquire and process information and provide feedback. Starting at the device, where information originates, we partition functions around task needs and reduce support costs repeated at every node.</p><h2 id="iot-edge-architecture-and-intelligent-computing" tabindex="-1">IoT Edge Architecture and Intelligent Computing <a class="header-anchor" href="#iot-edge-architecture-and-intelligent-computing" aria-label="Permalink to &quot;IoT Edge Architecture and Intelligent Computing&quot;">​</a></h2><p>Basic sensing tasks, such as temperature, light, and some low-rate vibration monitoring, produce small observations but require many nodes to operate for long periods. For these resource-constrained devices, we investigate micro-computing and micro-communication to reduce the overhead of general-purpose control, peripheral operations, and wireless interaction. Energy management aligns task execution with available energy.</p><p>Audio, image, and video tasks require more computation at the device. We are extending our work toward audio processing that combines spiking neural networks (SNNs) with energy-aware control, simplified computing arrays and specialized reconfigurable execution, and algorithm–chip co-design for edge intelligence.</p><h2 id="embodied-intelligent-sensing-and-interaction" tabindex="-1">Embodied Intelligent Sensing and Interaction <a class="header-anchor" href="#embodied-intelligent-sensing-and-interaction" aria-label="Permalink to &quot;Embodied Intelligent Sensing and Interaction&quot;">​</a></h2><p>We investigate passive wireless sensing, physical-signal processing, and structured representations of images and video. Sensor-to-Semantics (S2S) explores how a visual front end can organize primitives, local structure, and task-relevant evidence so that downstream systems consume information as needed, reducing unnecessary repeated computation and transmission.</p><p>Front-end processing must retain information needed by downstream tasks, with task outcomes used to assess the impact of information loss. Low-cost audio and visual sensing remain ongoing research directions supporting spatial understanding and embodied interaction.</p><h2 id="swarm-collaborative-intelligence-and-communication" tabindex="-1">Swarm Collaborative Intelligence and Communication <a class="header-anchor" href="#swarm-collaborative-intelligence-and-communication" aria-label="Permalink to &quot;Swarm Collaborative Intelligence and Communication&quot;">​</a></h2><p>We study low-power wireless communication, regional information aggregation, distributed intelligence, and collaborative decision-making. Differences in resources between edge infrastructure and devices offer opportunities to share support functions and simplify wireless interaction. For low-rate sensing data and some front-end-processed audio and visual information, we investigate transmission suited to narrowband links while considering response time, reliability, and security.</p><h2 id="intelligent-information-processing-and-applications" tabindex="-1">Intelligent Information Processing and Applications <a class="header-anchor" href="#intelligent-information-processing-and-applications" aria-label="Permalink to &quot;Intelligent Information Processing and Applications&quot;">​</a></h2><p>We develop methods for data mining, recommendation systems, and intelligent data analysis, organizing information from multiple sensing sources into representations for modeling and decision-making. Prototypes and application demonstrations evaluate information quality, end-to-end overhead, and sustained operation on concrete tasks, connecting low-cost information acquisition with intelligent applications in real settings.</p><h2 id="related-information" tabindex="-1">Related Information <a class="header-anchor" href="#related-information" aria-label="Permalink to &quot;Related Information&quot;">​</a></h2><ul><li><a href="/projects">Representative research projects</a></li><li><a href="/publication">Selected publications</a></li><li><a href="/people">Laboratory members</a></li><li><a href="/contact">Contact us</a></li></ul>',19)])])}const p=i(t,[["render",r]]);export{g as __pageData,p as default};
